<?php
$title='Audit Reports';$subtitle='AI growth reports sent to prospects as branded PDFs';
if(is_post()&&($_POST['a']??'')==='delete'){$r=DB::row('SELECT * FROM reports WHERE id=?',[(int)$_POST['id']]);if($r){@unlink(ROOT.'/'.$r['pdf']);DB::q('DELETE FROM reports WHERE id=?',[$r['id']]);event($r['lead_id'],'note','Report deleted');}flash('Report deleted.');redirect(url('reports'));}
$q=trim($_GET['q']??'');$a=[];$w='1=1';
if($q!==''){$w='l.name LIKE ?';$a[]='%'.$q.'%';}
$rows=DB::all("SELECT r.id,r.token,r.views,r.created_at,r.pdf,l.id lid,l.name,l.category,l.website,l.web_score,l.map_score,l.stage,p.name pname FROM reports r JOIN leads l ON l.id=r.lead_id LEFT JOIN prompts p ON p.id=r.prompt_id WHERE $w ORDER BY r.id DESC LIMIT 300",$a);
?>
<?php $k=DB::row('SELECT COUNT(*) t,SUM(views>0) v,SUM(views) tv,SUM(created_at>=NOW()-INTERVAL 7 DAY) wk FROM reports');?><div class="stats"><?=kpi('Reports created',(int)$k['t'],'file','violet',(int)$k['wk'].' this week')?><?=kpi('Opened by prospects',(int)$k['v'],'eye','teal',$k['t']?round($k['v']/$k['t']*100).'% open rate':'—')?><?=kpi('Total views',(int)$k['tv'],'activity','sky','report link opens')?><?=kpi('Design & prompts','Edit','layers','amber','colours, doodles, AI prompts',url('templates'))?></div>
<form class="fbar" method="get"><input type="hidden" name="r" value="reports"><label class="srch"><?=icon('search')?><input name="q" value="<?=e($q)?>" placeholder="Search by business name…"></label><button class="btn btn-n">Search</button><a class="btn" href="<?=url('templates',['t'=>'design'])?>"><?=icon('image')?>Report design</a></form>
<div class="card p0"><?php if(!$rows):?><div class="empty"><?=icon('file')?><h4>No reports yet</h4><p>Open a search, select leads and click <b>Initiate Process</b> to generate AI audit reports.</p></div><?php else:?><div class="tw"><table class="tbl"><thead><tr><th class="sn">#</th><th>Business</th><th>Type</th><th>Web</th><th>Maps</th><th>Prompt</th><th>Views</th><th>Stage</th><th>Created</th><th></th></tr></thead><tbody><?php $sn=0;foreach($rows as $r):$sn++;?><tr><td class="sn"><?=$sn?></td><td><a href="<?=url('lead',['id'=>$r['lid']])?>"><b><?=e($r['name'])?></b></a><br><small class="muted"><?=e($r['category'])?></small></td><td><?=$r['website']?'<span class="bdg c-blue">Website + Maps</span>':'<span class="bdg c-amber">Maps + website pitch</span>'?></td><td><?=$r['web_score']===null?'<span class="muted">—</span>':'<span class="sc sc-'.($r['web_score']>=75?'g':($r['web_score']>=50?'a':'r')).'">'.(int)$r['web_score'].'</span>'?></td><td><?=$r['map_score']===null?'<span class="muted">—</span>':'<span class="sc sc-'.($r['map_score']>=75?'g':($r['map_score']>=50?'a':'r')).'">'.(int)$r['map_score'].'</span>'?></td><td class="sm"><?=e($r['pname']??'—')?></td><td><?=(int)$r['views']?></td><td><?=badge($r['stage'])?></td><td class="muted"><?=ago($r['created_at'])?></td><td class="act"><a class="ib" href="report.php?t=<?=e($r['token'])?>" target="_blank" title="View"><?=icon('eye')?></a><a class="ib" href="report.php?t=<?=e($r['token'])?>&dl=1" title="Download"><?=icon('download')?></a><button class="ib" title="Copy public link" onclick="A.copy('<?=e(base_url('report.php?t='.$r['token']))?>')"><?=icon('link')?></button><form method="post" onsubmit="return confirm('Delete this report?')"><?=csrf_field()?><input type="hidden" name="a" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="ib red"><?=icon('trash')?></button></form></td></tr><?php endforeach?></tbody></table></div><?php endif?></div>
